local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[402407]=b({e[9045],402407,13,58,150,"「あら？　もうこんな時間……。うふふ……ここはお湯加減もちょうど良いし、邪魔も入らないから……つい長湯しちゃうわね。でも、たまには細かいことを忘れて、ゆ～っくり羽を伸ばしても、大丈夫よね？」",200024,2,"deco/character/beijianshahezi_WQ",1,2816,5000,1390,889,10666,8000,5633,4333,14000,8000,5333,"beijianshahezi_wq"},h)g[402501]=b({e[46057],402501,false,81,151,false,200025,false,"deco/character/aiyin",302002,60,1,false,false,false,-74,"1",false,false,false,false,false,false,false,"0,250,0.98","-50,0,1",false,false,false,false,"-40,-20,1","0,-20,1",false,false,false,1833,836,400,1254,657,1731,2879,1254,657,1731,1139,"aiyin"},h)g[402502]=b({e[12034],402502,1,4,152,"「尻尾、ちゃんと掴んどけよ？ 狩りの間にはぐれたらまずいからな。\nまぁ安心してくれ、本当に迷子になっちまっても、俺が絶対見つけてやるから！ ハハハッ！」",200025,1,"deco/character/aiyin_0",302002,60,1,1865,824,400,938,643,2418,3291,938,643,2418,1141,false,false,false,false,false,false,false,false,false,false,false,false,"aiyin_0"},h)g[402503]=b({e[21034],402503,2,48,153,"「俺普段は森で狩ってばっかだけど、波に乗るのも上手いんだぜ。一緒に海の鼓動を感じてみねぇ？　ハッハー！」",200025,2,"deco/character/aiyin_YZ",false,false,false,false,false,false,false,false,false,false,false,"160,0,0.9315",1977,869,436,621,537,2625,3093,621,586,2625,1261,false,false,false,false,false,false,false,false,false,false,false,false,"aiyin_xr"},h)g[402504]=b({e[21034],402504,3,24,154,"「へえ？　さすがハロウィン、獲物の方からのこのこ現れるなんてな。道にでも迷ったのか？　可愛い顔しやがって。そうだな……ハンデをやるよ、先に39メートル走っていいぜ。後から追ってやるから。」",200025,2,"deco/character/aiyin_WS",false,false,1,false,false,false,false,false,false,false,false,"170,0,0.94",1796,843,403,241,212,3590,3366,585,544,2902,1261,false,false,false,false,false,false,false,false,false,false,false,false,"aiyin_ws"},h)g[402505]=b({e[17057],402505,5,30,155,"「うわー、すっげーキレーな雪だな。新年早々縁起がいいぜ。\n今年は初詣に来る人がめちゃくちゃ多いんだってな、もう列がすげーとか何とか。\nいや、俺はそんな人混みに行く気はないけど。だって、今日俺が一番捕まえたい『獲物』は、目の前にいるからな。ハハハ！\n……いや、冗談だって。つか寒ぃだろ？ だったら、もうちょいこっち寄りな。\n一つ秘密を教えてやる。狐の懐ってのは、冬で一番温かい罠なんだ。\n一度目をつけられたら、もう逃げられねぇぞ。」",200025,2,"deco/character/aiyin_yd",false,false,false,false,false,false,false,"","aiyin_yd"},h)g[402601]=b({e[32057],402601,false,82,156,false,200026,false,"deco/character/chutao",302002,60,false,false,false,false,-38,"1",false,false,false,false,false,false,false,"0,-180,1.04","-70,-50,1","0,-50,1",false,false,false,"-40,-40,1","-30,-40,1","chutao",false,0},h)g[402602]=b({e[13057],402602,1,4,157,"「はわわー！ どうしよう、お茶会に間に合わなくなっちゃうのです……！\nうさぎさん、助けてほしいのです！」",200026,1,"deco/character/chutao_0",302002,60,false,1,"chutao_0",false,0},h)g[402603]=b({e[13057],402603,6,26,158,"「雛桃がうさぎさんを好きな理由？　えー？　黄梅が咲いたら春はすぐそこっていうのと同じような感じかな～と思うのです！」",200026,2,"deco/character/chutao_CJ",false,false,false,1,"chutao_cj",false,0},h)g[402604]=b({e[12057],402604,8,83,159,"「今日も遅刻せずに来てくれたのですね～。お茶会は、もうすぐ始まるのです！　大きなお茶会でお給仕するのは初めてだけど、うさぎさんのために雛桃頑張るのです！　だからうさぎさん、いっぱい楽しんでいってね！」",200026,2,"deco/character/chutao_NP",false,false,1,"chutao_np",false,0},h)g[402605]=b({e[21057],402605,4,52,160,"「不思議の国も、今は雪なのです……？　ウサギさんと一緒に、見に行きたいのです。」",200026,2,"deco/character/chutao_SD",false,false,false,false,false,false,false,"1",false,false,false,"240,-300,1","chutao_sd",false,0},h)g[402606]=b({e[17045],402606,2,84,161,"「わぁ……！　雛桃、レモネードの海をおよぐ人魚さんになったのです！\nということは、つぎのお茶会のテーマは、ふしぎの国でのプールあそびなのです？\nこんないいことがおこるのは、うさぎさんといっしょにいるからなのです！」",200026,2,"deco/character/chutao_xr",false,false,false,false,false,false,false,"",1,3816,5000,2038,3806,6666,5900,10000,5533,12000,8000,3333,"chutao_xr",false,0},h)g[402607]=b({e[17046],402607,9,31,162,"「ん～、あれ、ウサギさん……？\nさっきまでいた不思議の国、どこにいっちゃったのです？\nティーポットさんのためのくものケーキ、やきあがったばかりなのに……。\nウサギさん、もういちど、ゆめのなかへみんなをさがしに行くのです！\nいまなら、さっきのゆめのこと、まだ思い出せるかもしれないのです！」",200026,2,"deco/character/402607",false,false,false,false,false,false,false,"",3164,5000,1627,3067,8000,8666,16666,5500,14000,8000,8000,false,false,0},h)g[402701]=b({e[46059],402701,false,85,163,false,200027,false,"deco/character/402701",302002,60,1,1,false,false,false,false,false,false,false,false,false,false,false,"20,460,0.95","-90,